<?php
 namespace Pterodactyl\Services\Dezerx\Staff; use Pterodactyl\Models\Dezerx\StaffRequest; use Pterodactyl\Models\Subuser; class StaffAccess { private static array $cache = []; public static function usable(?Subuser $subuser): bool { if ($subuser === null) { return false; } $id = $subuser->dezerx_staff_request_id; if ($id === null) { return true; } $id = (int) $id; if (array_key_exists($id, self::$cache)) { return self::$cache[$id]; } $request = StaffRequest::query() ->whereKey($id) ->first(['id', 'status', 'expires_at', 'staff_id']); $usable = $request !== null && $request->isUsable() && (int) $request->staff_id === (int) $subuser->user_id; return self::$cache[$id] = $usable; } public static function forget(): void { self::$cache = []; } } 